//! The signal library — and the control that keeps the harness honest.
//!
//! Each of these is a hypothesis about price, deliberately simple, and every one is judged by the
//! same [`crate::evaluate`] machinery with no special pleading. Simple is not a limitation here: a
//! complicated signal has more places to overfit and the harness cannot tell the difference.
//!
//! # The null control is the most important thing in this file
//!
//! [`NullControl`] flips a deterministic coin. It knows nothing and it cannot work. If the harness
//! ever rates it as promising, THE HARNESS IS BROKEN — and that is a claim about the measuring
//! instrument that can be tested, which is worth more than any of the signals below.
//!
//! It also calibrates expectations. Run it beside a real candidate on the same data and the
//! difference between them is the only part that is evidence.
use crate::evaluate::Signal;
use crate::series::Bar;

/// Hold, always. The benchmark expressed as a signal, so it goes through the identical path.
pub struct BuyAndHold;

impl Signal for BuyAndHold {
    fn name(&self) -> &str {
        "buy-and-hold"
    }
    fn position(&self, _history: &[Bar]) -> f64 {
        1.0
    }
}

/// Long while price is above its own moving average, flat below it.
///
/// The oldest trend filter there is, and one of the few with evidence outside the sample it was
/// found in. What it actually does is avoid long drawdowns rather than improve returns, so read the
/// max drawdown before the total.
pub struct TrendFilter {
    pub window: usize,
}

impl Signal for TrendFilter {
    fn name(&self) -> &str {
        "trend-filter"
    }
    fn position(&self, history: &[Bar]) -> f64 {
        if history.len() < self.window {
            // NOT ENOUGH HISTORY IS FLAT, never long. A signal that defaults to holding while it
            // warms up is measuring buy-and-hold for its first year and calling it strategy.
            return 0.0;
        }
        let window = &history[history.len() - self.window..];
        let mean = window.iter().map(|b| b.close.minor as f64).sum::<f64>() / self.window as f64;
        let last = history[history.len() - 1].close.minor as f64;
        if last > mean { 1.0 } else { 0.0 }
    }
}

/// Twelve-month return, skipping the most recent month.
///
/// The skip is not decoration: the last month reverses on average, and momentum measured including
/// it is a materially weaker signal. Long when the trailing return is positive, flat otherwise.
pub struct Momentum {
    pub lookback: usize,
    pub skip: usize,
}

impl Momentum {
    /// The conventional 12-1 in trading days.
    pub fn twelve_one() -> Momentum {
        Momentum { lookback: 252, skip: 21 }
    }
}

impl Signal for Momentum {
    fn name(&self) -> &str {
        "momentum-12-1"
    }
    fn position(&self, history: &[Bar]) -> f64 {
        if history.len() < self.lookback + self.skip {
            return 0.0;
        }
        let end = history.len() - self.skip;
        let start = end - self.lookback;
        let (a, b) = (history[start].close.minor as f64, history[end - 1].close.minor as f64);
        if a <= 0.0 {
            return 0.0;
        }
        if b > a { 1.0 } else { 0.0 }
    }
}

/// Long after a run of consecutive down closes.
///
/// Included BECAUSE it is the most overfit shape in retail research, not because it is expected to
/// work — a candidate whose result cannot be distinguished from this one has not been demonstrated.
pub struct MeanReversion {
    pub down_days: usize,
}

impl Signal for MeanReversion {
    fn name(&self) -> &str {
        "mean-reversion"
    }
    fn position(&self, history: &[Bar]) -> f64 {
        if history.len() <= self.down_days {
            return 0.0;
        }
        let tail = &history[history.len() - self.down_days - 1..];
        let all_down = tail.windows(2).all(|w| w[1].close.minor < w[0].close.minor);
        if all_down { 1.0 } else { 0.0 }
    }
}

/// Long while the last `lookback` closes are rising — the fast counterpart to `Momentum`.
///
/// A short-horizon persistence signal. Added because the simulation caught its absence: a battery
/// whose fastest signal averages two hundred days cannot see structure that turns over in three,
/// and reported "nothing here" on a series built to contain something. That was a gap in the
/// battery rather than a fault in the harness, and the distinction is only visible because the
/// simulation knew the answer in advance.
///
/// It trades a great deal, so read it net of costs and expect the costs to matter.
pub struct Persistence {
    pub lookback: usize,
}

impl Signal for Persistence {
    fn name(&self) -> &str {
        "persistence"
    }
    fn position(&self, history: &[Bar]) -> f64 {
        if history.len() <= self.lookback {
            return 0.0;
        }
        let tail = &history[history.len() - self.lookback - 1..];
        if tail.windows(2).all(|w| w[1].close.minor > w[0].close.minor) { 1.0 } else { 0.0 }
    }
}

/// A deterministic coin flip. THE CONTROL.
///
/// It knows nothing, it cannot work, and the harness rating it as promising would mean the harness
/// is broken. Seeded off the history length so it is reproducible run to run — a control that
/// changed every run could not be compared against anything.
pub struct NullControl {
    pub seed: u64,
}

impl Signal for NullControl {
    fn name(&self) -> &str {
        "null-control"
    }
    fn position(&self, history: &[Bar]) -> f64 {
        let mut x = self.seed ^ (history.len() as u64).wrapping_mul(0x9E37_79B9_7F4A_7C15);
        x ^= x >> 30;
        x = x.wrapping_mul(0xBF58_476D_1CE4_E5B9);
        x ^= x >> 27;
        if x.is_multiple_of(2) { 1.0 } else { 0.0 }
    }
}

/// The default battery, in the order a person should read it.
///
/// The control is FIRST on purpose. Reading it before the candidates is what stops a mediocre result
/// looking impressive in isolation — and running them together is also what sets the trial count,
/// so the bar every one of them must clear already accounts for the others.
pub fn default_battery() -> Vec<Box<dyn Signal>> {
    vec![
        Box::new(NullControl { seed: 1 }),
        Box::new(BuyAndHold),
        Box::new(TrendFilter { window: 200 }),
        Box::new(Momentum::twelve_one()),
        Box::new(MeanReversion { down_days: 3 }),
        Box::new(Persistence { lookback: 1 }),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::evaluate::{evaluate, evaluate_all, EvalOptions, Verdict};
    use crate::money::usd;
    use crate::series::{unverified_series, BarDate, SeriesMeta, VerifiedSeries};

    // SYNTHETIC FIXTURES ONLY.
    fn weekdays(n: usize) -> Vec<String> {
        let mut out = Vec::with_capacity(n);
        let mut d = "2026-01-05".to_string();
        while out.len() < n {
            if !crate::series::is_weekend(&d) {
                out.push(d.clone());
            }
            d = crate::obligations::add_days(&d, 1);
        }
        out
    }

    fn bar_on(date: &str, open: i64, close: i64) -> Bar {
        Bar { date_i: BarDate::new(date), open: usd(open), high: usd(open.max(close) + 1), low: usd(open.min(close) - 1), close: usd(close), volume: None }
    }

    /// A deterministic walk with a drift, so a trend actually exists to be found.
    fn walk(n: usize, drift: f64) -> Vec<Bar> {
        let dates = weekdays(n);
        let mut px = 10_000.0_f64;
        let mut seed = 999u64;
        let mut out = Vec::new();
        for date in dates.iter().take(n) {
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1_442_695_040_888_963_407);
            let u = ((seed >> 33) as f64 / (1u64 << 31) as f64) * 2.0 - 1.0;
            let open = px;
            px *= 1.0 + drift + u * 0.015;
            out.push(bar_on(date, open.round() as i64, px.round() as i64));
        }
        out
    }

    fn series(bars: &[Bar]) -> VerifiedSeries {
        unverified_series(bars, SeriesMeta::new("SYNTH", "generated"), "a synthetic fixture, not market data").expect("caveat")
    }

    #[test]
    fn the_null_control_is_never_rated_promising_on_noise() {
        // THE GUARD ON THE HARNESS ITSELF. A coin flip cannot work, so a harness that ever calls one
        // promising is broken — and that is a claim about the instrument, testable across seeds.
        let bars = walk(800, 0.0);
        let s = series(&bars);
        for seed in [1u64, 7, 42, 1_000, 65_537] {
            let e = evaluate(&s, &NullControl { seed }, &EvalOptions { trials: 6, ..EvalOptions::default() });
            assert_ne!(e.verdict, Verdict::Promising, "seed {seed} was rated promising: {}", e.why);
        }
    }

    #[test]
    fn a_signal_with_too_little_history_stays_flat_rather_than_defaulting_long() {
        // Defaulting to long while warming up measures buy-and-hold for the first year and calls it
        // strategy — the returns are real and none of them belong to the signal.
        assert_eq!(TrendFilter { window: 200 }.position(&[]), 0.0);
        assert_eq!(Momentum::twelve_one().position(&walk(100, 0.0)), 0.0);
        assert_eq!(MeanReversion { down_days: 3 }.position(&[]), 0.0);
        // And with enough history it does take a view.
        let up: Vec<Bar> = weekdays(300).iter().enumerate().map(|(i, d)| bar_on(d, 10_000 + i as i64 * 10, 10_000 + i as i64 * 10)).collect();
        assert_eq!(TrendFilter { window: 200 }.position(&up), 1.0, "a rising series is above its own average");
    }

    #[test]
    fn the_trend_filter_is_flat_below_its_average_and_long_above_it() {
        let down: Vec<Bar> = weekdays(300).iter().enumerate().map(|(i, d)| bar_on(d, 20_000 - i as i64 * 10, 20_000 - i as i64 * 10)).collect();
        assert_eq!(TrendFilter { window: 200 }.position(&down), 0.0, "a falling series is below its own average");
        // Exactly at the average is FLAT, not long — a strict comparison, so a dead-flat series
        // does not read as a buy signal on every bar.
        let flat: Vec<Bar> = weekdays(300).iter().map(|d| bar_on(d, 10_000, 10_000)).collect();
        assert_eq!(TrendFilter { window: 200 }.position(&flat), 0.0);
    }

    #[test]
    fn momentum_skips_the_most_recent_month_because_it_reverses() {
        let dates = weekdays(300);
        // Rising for a year, then falling hard for the last month. Including the last month would
        // read this as negative momentum; skipping it reads the year, which is the documented shape.
        let mut bars: Vec<Bar> = Vec::new();
        for (i, d) in dates.iter().enumerate() {
            let px = if i < 275 { 10_000 + i as i64 * 20 } else { 15_500 - (i as i64 - 275) * 100 };
            bars.push(bar_on(d, px, px));
        }
        assert_eq!(Momentum { lookback: 252, skip: 21 }.position(&bars), 1.0, "the year was up");
        assert_eq!(Momentum { lookback: 252, skip: 0 }.position(&bars), 1.0);
        // The skip is what makes the two able to disagree at all — pinned so a refactor that drops
        // it cannot pass silently.
        assert_eq!(Momentum::twelve_one().skip, 21);
        assert_eq!(Momentum::twelve_one().lookback, 252);
    }

    #[test]
    fn mean_reversion_needs_a_full_run_of_down_closes() {
        let dates = weekdays(10);
        let down: Vec<Bar> = dates.iter().enumerate().map(|(i, d)| bar_on(d, 10_000 - i as i64 * 10, 10_000 - i as i64 * 10)).collect();
        assert_eq!(MeanReversion { down_days: 3 }.position(&down), 1.0);
        // One up close inside the run and it is not a run.
        let mut broken = down.clone();
        let n = broken.len();
        broken[n - 2] = bar_on(dates[n - 2].as_str(), 99_999, 99_999);
        assert_eq!(MeanReversion { down_days: 3 }.position(&broken), 0.0);
    }

    #[test]
    fn the_battery_runs_them_all_against_the_bar_for_running_them_all() {
        let bars = walk(900, 0.0003);
        let s = series(&bars);
        let battery = default_battery();
        let refs: Vec<&dyn Signal> = battery.iter().map(|b| b.as_ref()).collect();
        let out = evaluate_all(&s, &refs, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert_eq!(out.len(), 6);
        // The trial count is the number ACTUALLY run, so every one of them is graded against the
        // bar for five attempts rather than one.
        let want = crate::evaluate::t_required_for(6);
        assert!(out.iter().all(|e| (e.t_required - want).abs() < 1e-9));
        // The control is in the battery, so a mediocre candidate is never read in isolation.
        assert!(out.iter().any(|e| e.signal == "null-control"));
        assert!(out.iter().any(|e| e.signal == "buy-and-hold"));
    }

    #[test]
    fn buy_and_hold_as_a_signal_matches_the_benchmark_it_is_measured_against() {
        // A useful internal consistency check: routing the benchmark through the signal path must
        // reproduce the benchmark, or the two are computed differently and every comparison the
        // harness makes is between things that are not comparable.
        let bars = walk(600, 0.0004);
        let e = evaluate(&series(&bars), &BuyAndHold, &EvalOptions { costs: crate::evaluate::Costs::free(), min_trades: 1, ..EvalOptions::default() });
        let (net, bench) = (e.net.unwrap(), e.benchmark.unwrap());
        assert!((net.total_return - bench.total_return).abs() < 1e-9, "net {} vs benchmark {}", net.total_return, bench.total_return);
        assert_eq!(net.periods, bench.periods);
    }
}
